"use client";

import * as React from "react";

import { UiToastStack, type UiToastStackHandle } from "@/components/lumesec/ui-toast-stack";

export function Example() {
  const toasts = React.useRef<UiToastStackHandle>(null);
  return (
    <div className="grid gap-3">
      <UiToastStack ref={toasts} trigger={false} />
      <button
        type="button"
        onClick={() => toasts.current?.show({ title: "Saved", description: "All changes are stored.", tone: "success" })}
      >
        Save
      </button>
    </div>
  );
}
